// Swatch libraries for the Swatches panel menu, generated by the color
// engine (original palettes, no proprietary color books). The commands
// register at startup; the color engine loads when one of them runs.
import type { Editor } from '../../editor';
import { registerCommand } from '../../app/registry';
import { formDialog } from '../../ui/dialog';
import type { HarmonyScheme, SwatchKind } from '../../color/color-info';

const engine = () => import('../../color/color-management');

const LIBRARIES: [SwatchKind, string][] = [
  ['hue-ramps', 'Hue Ramps Library…'], ['grays', 'Grays Library…'], ['web-safe', 'Web Safe Colors Library…'], ['pastels', 'Pastels Library…'], ['earth', 'Earth Tones Library…'],
];
const HARMONIES: [HarmonyScheme, string][] = [
  ['complementary', 'Complementary'], ['analogous', 'Analogous'], ['triadic', 'Triadic'], ['split-complementary', 'Split Complementary'], ['tetradic', 'Tetradic'], ['monochromatic', 'Monochromatic'],
];

async function load(e: Editor, name: string, colors: string[]) {
  const v = await formDialog(`Load ${name}`, [
    { name: 'how', label: `${colors.length} swatches`, value: 'append', type: 'select', options: [['append', 'Append to current swatches'], ['replace', 'Replace current swatches']] },
  ], 'OK');
  if (!v) return;
  const { addSwatch, replaceSwatches } = await import('../panels');
  if (v.how === 'replace') replaceSwatches(e, colors);
  else addSwatch(e, ...colors);
  e.message(`${v.how === 'replace' ? 'Loaded' : 'Appended'} ${name} (${colors.length} swatches).`);
}

export function installSwatchLibraries() {
  for (const [kind, label] of LIBRARIES)
    registerCommand({
      id: `swatches.library-${kind}`,
      label,
      recordable: false,
      run: async (e) => {
        const { generateSwatchLibrary } = await engine();
        await load(e, label.replace(' Library…', ''), generateSwatchLibrary(kind).swatches.map((s) => s.hex));
      },
    });
  for (const [scheme, label] of HARMONIES)
    registerCommand({
      id: `swatches.harmony-${scheme}`,
      label: `${label} Harmony from Foreground`,
      recordable: false,
      run: async (e) => {
        const [{ addSwatch }, { harmonySwatches }] = await Promise.all([import('../panels'), engine()]);
        const colors = harmonySwatches(e.color, scheme).map((s) => s.hex);
        addSwatch(e, ...colors);
        e.message(`Appended a ${label.toLowerCase()} harmony of ${e.color}.`);
      },
    });
}
